/// shieldBoosting
fn e4(cx: &mut Cx, me: It) {
    let mut v_amount: f64 = cx.attr(me, 68);
    let mut v_speed: f64 = (cx.attr(me, 73) / 1000.0);
    cx.extra_increase(1000000, (v_amount / v_speed));
}
/// targetAttack
fn e10(cx: &mut Cx, me: It) {
    cx.set_reload_time(me, 1000.0);
}
