/// projectileFired
fn e34(cx: &mut Cx, me: It) {
    let mut v_rt: f64 = cx.attr(me, 1795);
    if (!((v_rt) != 0.0)) {
        cx.set_reload_time(me, 10000.0);
    } else {
        cx.set_reload_time(me, v_rt);
    }
}
/// warpDisrupt
fn e39(cx: &mut Cx, me: It) {
    if (!cx.ctx(Ctx::Projected)) {
        return;
    }
    if ((cx.attr(cx.ship, 872)) != 0.0) {
        return;
    }
    if (cx.attr(me, 54) < cx.proj_range.unwrap_or(0.0)) {
        return;
    }
    cx.op(cx.ship, Op::Increase, 104, cx.attr(me, 105), O { skill: 0, stack: false, group: 0, post: false, kw: true });
}
/// powerBooster
fn e48(cx: &mut Cx, me: It) {
    cx.set_reload_time(me, 10000.0);
    cx.set_force_reload(me, true);
    if (cx.charge_of(me) == NONE) {
        return;
    }
    let mut v_capAmount: f64 = { let t1 = cx.charge_attr(me, 67); if t1 != 0.0 { t1 } else { 0.0 } };
    cx.set_intermediary(me, 6, (-v_capAmount));
}
